"""Lossless, deterministic VIR v1 encoding.

One line per record, with a required ``V1;WIDTHxHEIGHT`` header. Records:
``O1:label|bbox|confidence``, ``A:O1|name|\"value\"|confidence``,
``T1:\"text\"|bbox|confidence[|language]``, ``R:O1>predicate>O2|confidence``,
``C:\"caption\"|confidence``, ``S:\"tag\"|confidence``, ``Q:\"query\"``.

bbox is x1,y1,x2,y2. Quoted fields use JSON string escaping with literal
Unicode. Unquoted strings percent-escape %, |, >, :, LF and CR using uppercase
ASCII hex (%25, %7C, %3E, %3A, %0A, %0D). No lossy rounding is performed.
Record order is stable and follows input order within each scene collection.
"""

from __future__ import annotations

import json

from virvision.scene import BBox, VisualScene


_ESCAPES = {"%": "%25", "|": "%7C", ">": "%3E", ":": "%3A", "\n": "%0A", "\r": "%0D"}


def escape_field(value: str) -> str:
    """Escape reserved characters in a VIR unquoted string, exactly once."""
    return "".join(_ESCAPES.get(char, char) for char in value)


def _float(value: float) -> str:
    # repr is Python's shortest decimal round trip. Removing a trailing .0 or
    # leading zero preserves its numeric value, including negative zero.
    result = repr(value)
    if result.endswith(".0"):
        result = result[:-2]
    if result.startswith("0."):
        result = result[1:]
    elif result.startswith("-0."):
        result = "-" + result[2:]
    return result


def _bbox(box: BBox) -> str:
    return ",".join(_float(value) for value in (box.x1, box.y1, box.x2, box.y2))


def _quote(value: str) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def serialize_vir(scene: VisualScene) -> str:
    """Encode a validated scene without truncation, rounding or raw pixels."""
    if not isinstance(scene, VisualScene):
        raise ValueError("scene must be a VisualScene")
    lines = [f"V1;{scene.width}x{scene.height}"]
    if scene.query is not None:
        lines.append(f"Q:{_quote(scene.query)}")
    for obj in scene.objects:
        lines.append(
            f"{obj.id}:{escape_field(obj.label)}|{_bbox(obj.bbox)}|{_float(obj.confidence)}"
        )
        for attr in obj.attributes:
            lines.append(
                f"A:{obj.id}|{escape_field(attr.name)}|{_quote(attr.value)}|{_float(attr.confidence)}"
            )
    for item in scene.texts:
        line = f"{item.id}:{_quote(item.text)}|{_bbox(item.bbox)}|{_float(item.confidence)}"
        if item.language is not None:
            line += f"|{escape_field(item.language)}"
        lines.append(line)
    for relation in scene.relations:
        lines.append(
            f"R:{relation.source}>{escape_field(relation.predicate)}>{relation.target}|{_float(relation.confidence)}"
        )
    if scene.caption is not None:
        lines.append(f"C:{_quote(scene.caption.text)}|{_float(scene.caption.confidence)}")
    for tag in scene.tags:
        lines.append(f"S:{_quote(tag.text)}|{_float(tag.confidence)}")
    return "\n".join(lines)
